## SQL (run once in the Supabase SQL Editor)
sql
create extension if not exists pgcrypto with schema extensions;

create table public.audit_log (
  seq bigint primary key,
  ts timestamptz not null,
  event_type text not null,
  action text not null,
  status text not null check (status in ('success','error','pending','rejected')),
  actor text,
  actor_type text not null check (actor_type in ('human','system','ai_agent')),
  reason text,
  workflow_id text,
  workflow_name text,
  workflow_version text,
  execution_id text,
  correlation_id text,
  details jsonb,
  payload_hash text,
  schema_version int not null default 1,
  prev_hash text not null,
  hash text not null
);

create or replace function public.audit_hash(r public.audit_log)
returns text language sql immutable set search_path = '' as $$
  select encode(extensions.digest(concat_ws('|',
    r.prev_hash, r.seq::text,
    to_char(r.ts at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'),
    r.event_type, r.action, r.status,
    coalesce(r.actor,''), r.actor_type, coalesce(r.reason,''),
    coalesce(r.workflow_id,''), coalesce(r.workflow_name,''),
    coalesce(r.workflow_version,''), coalesce(r.execution_id,''),
    coalesce(r.correlation_id,''), coalesce(r.details::text,''),
    coalesce(r.payload_hash,''), r.schema_version::text),
    'sha256'), 'hex');
$$;

create or replace function public.audit_log_chain()
returns trigger language plpgsql set search_path = '' as $$
declare last_row public.audit_log;
begin
  perform pg_advisory_xact_lock(hashtext('audit_log_chain'));
  select * into last_row from public.audit_log order by seq desc limit 1;
  new.seq := coalesce(last_row.seq, 0) + 1;
  new.ts := clock_timestamp();
  new.prev_hash := coalesce(last_row.hash, 'GENESIS');
  new.hash := public.audit_hash(new);
  return new;
end $$;

create trigger trg_audit_chain before insert on public.audit_log
  for each row execute function public.audit_log_chain();

create or replace function public.audit_log_block()
returns trigger language plpgsql set search_path = '' as $$
begin raise exception 'audit_log is append-only'; end $$;

create trigger trg_audit_no_change before update or delete on public.audit_log
  for each row execute function public.audit_log_block();
create trigger trg_audit_no_truncate before truncate on public.audit_log
  for each statement execute function public.audit_log_block();

alter table public.audit_log enable row level security;
revoke all on public.audit_log from anon, authenticated;

create or replace function public.audit_verify()
returns table(broken_seq bigint, reason text)
language sql stable set search_path = '' as $$
  with chk as (
    select a as rec,
      lag(a.hash) over (order by a.seq) as expected_prev,
      lag(a.seq) over (order by a.seq) as prev_seq
    from public.audit_log a)
  select (rec).seq,
    case
      when (rec).seq <> coalesce(prev_seq, 0) + 1 then 'sequence gap (row deleted)'
      when (rec).prev_hash <> coalesce(expected_prev, 'GENESIS') then 'prev_hash mismatch (row altered or inserted)'
      else 'hash mismatch (row modified)'
    end
  from chk
  where (rec).seq <> coalesce(prev_seq, 0) + 1
     or (rec).prev_hash <> coalesce(expected_prev, 'GENESIS')
     or (rec).hash <> public.audit_hash(rec)
  order by 1 limit 1;
$$;
revoke execute on function public.audit_verify() from anon, authenticated;

