// Five fictional events that tell one short story. Replace them to test your own cases.
const cfg = $input.first().json;
const executionId = $execution.id !== undefined && $execution.id !== null ? String($execution.id) : 'manual';
const caseId = 'case-' + executionId;
const base = {
  source_workflow_id: $workflow.id,
  source_workflow_name: $workflow.name,
  source_workflow_version: cfg.workflow_version,
  source_execution_id: executionId,
  correlation_id: caseId,
};
const events = [
  { event_type: 'ai_query', action: 'answer_sop_question', status: 'success', actor: 'sop-agent', actor_type: 'ai_agent',
    reason: 'Answered from approved SOP text; question masked before the model call',
    details: { model: 'example-model', prompt_version: 'v1', sources: ['SOP-QC-002 v1.0'], found: true },
    payload: { question: '(masked) critical value procedure', answer: 'sample answer' } },
  { event_type: 'human_approval', action: 'request_review', status: 'pending', actor: 'review-workflow', actor_type: 'system',
    reason: 'AI answer sent to a reviewer before release',
    details: { reviewer_role: 'QA reviewer' },
    payload: { answer_id: 'ans-001' } },
  { event_type: 'human_approval', action: 'approve_answer', status: 'success', actor: cfg.demo_user, actor_type: 'human',
    reason: 'Reviewed against SOP-QC-002 v1.0',
    details: { decision: 'approved' },
    payload: { answer_id: 'ans-001', decision: 'approved' } },
  { event_type: 'data_change', action: 'publish_answer', status: 'success', actor: 'review-workflow', actor_type: 'system',
    reason: 'Approved answer released to the requester',
    details: { channel: 'form' },
    payload: { answer_id: 'ans-001', released: true } },
  { event_type: 'error', action: 'notify_requester', status: 'error', actor: 'review-workflow', actor_type: 'system',
    reason: 'Notification step failed (simulated)',
    details: { error_class: 'simulated' },
    payload: { answer_id: 'ans-001', notified: false } },
];
return events.map(function (event) {
  const payload = event.payload;
  const rest = {};
  Object.keys(event).forEach(function (key) {
    if (key !== 'payload') rest[key] = event[key];
  });
  rest.payload_text = JSON.stringify(payload);
  return { json: Object.assign({}, base, rest) };
});

// Rejects incomplete events instead of dropping them silently: an audit logger must fail loudly.
// Only action and status are mandatory. event_type defaults to workflow_event and actor_type to system.
const STATUS = ['success', 'error', 'pending', 'rejected'];
const ACTOR = ['human', 'system', 'ai_agent'];
function clean(v) {
  if (v === undefined || v === null || String(v).trim() === '') return null;
  return String(v).trim();
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const e = item.json;
  const missing = [];
  if (!clean(e.action)) missing.push('action');
  if (!clean(e.status)) missing.push('status');
  if (missing.length) throw new Error('Audit event rejected: missing ' + missing.join(', '));
  if (STATUS.indexOf(e.status) === -1) throw new Error('Audit event rejected: status must be one of ' + STATUS.join(', '));
  const eventType = clean(e.event_type) || 'workflow_event';
  const actorType = clean(e.actor_type) || 'system';
  if (ACTOR.indexOf(actorType) === -1) throw new Error('Audit event rejected: actor_type must be one of ' + ACTOR.join(', '));
  let details = null;
  if (e.details !== undefined && e.details !== null && e.details !== '') {
    details = typeof e.details === 'string' ? e.details : JSON.stringify(e.details);
    try { JSON.parse(details); } catch (err) { throw new Error('Audit event rejected: details is not valid JSON'); }
    if (details.length > 10000) throw new Error('Audit event rejected: details is larger than 10000 characters');
  }
  let correlationId = clean(e.correlation_id);
  if (!correlationId && clean(e.source_workflow_id) && clean(e.source_execution_id)) {
    correlationId = clean(e.source_workflow_id) + '-' + clean(e.source_execution_id);
  }
  out.push({ json: {
    event_type: eventType, action: clean(e.action), status: e.status,
    actor: clean(e.actor), actor_type: actorType, reason: clean(e.reason),
    workflow_id: clean(e.source_workflow_id), workflow_name: clean(e.source_workflow_name),
    workflow_version: clean(e.source_workflow_version), execution_id: clean(e.source_execution_id),
    correlation_id: correlationId, details: details, payload_hash: clean(e.payload_hash),
  } });
}
return out;
